mapper.select:
/* ReportResultMapper.findReports */ with cte_reports as ( select 'S26-1015-0231' as sample_id , 'RTI' as panel_code , '생식기 감염 종합' as panel_name , date '2026-10-15' as test_date , 5 as positive_count , date '2026-10-15' as report_created_date , 0 as print_count , null::timestamp as last_printed_at union all select 'S26-1015-0232' as sample_id , 'ABI' as panel_code , '호흡기 감염 종합' as panel_name , date '2026-10-15' as test_date , 5 as positive_count , date '2026-10-15' as report_created_date , 1 as print_count , timestamp '2026-10-16 00:00:00' as last_printed_at union all select 'S26-1015-0235' as sample_id , 'GTI' as panel_code , '소화기 감염 종합' as panel_name , date '2026-10-15' as test_date , 4 as positive_count , date '2026-10-15' as report_created_date , 0 as print_count , null::timestamp as last_printed_at ) select a.sample_id , a.panel_code , a.panel_name , a.test_date , a.positive_count , a.report_created_date , a.print_count , a.last_printed_at from cte_reports as a where a.test_date >= current_date - (#{periodMonths} * interval '1 month') and a.sample_id in
#{sampleId}
and a.panel_code = #{panelCode}
order by a.test_date desc , a.sample_id
